+          <button
+            type="button"
+            className="quiet-action quiet-action--danger"
+            disabled={!outcome.id}
+            onClick={() => {
+              if (!confirmDelete) {
+                setConfirmDelete(true);
+                return;
+              }
+              setConfirmDelete(false);
+              void deleteOutcome(outcomeId);
+            }}
+          >
+            {confirmDelete ? "Confirm remove" : "Remove"}
+          </button>
+        )}
+      </div>
+    </article>
+  );
+}

