+  font-family: var(--mono);
+  font-size: 0.8125rem;
+  text-align: right;
+  color: var(--text);
+}
+
+.gap__note {
+  color: var(--faint);
+  font-size: 0.8125rem;
+  line-height: 1.5;
+}
+
+/* ---------------------------------------------------------------- */
+/* Surfaces — the six catalog cards                                  */
+/* ---------------------------------------------------------------- */
+
+.surface {
+  display: flex;
+  flex-direction: column;
+  gap: 14px;
+  padding: 22px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-md);
+  background: var(--bg-raised);
+  box-shadow: var(--hairline);
+}
+
+.surface__head {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+}
+
+.surface__id {
+  font-family: var(--mono);
+  font-size: 0.6875rem;
+  font-weight: 600;
+  letter-spacing: 0.09em;
+  text-transform: uppercase;
+  color: var(--accent);
+}
+
+.surface__statement {
+  font-size: 0.9375rem;
+  font-weight: 500;
+  line-height: 1.5;
+}
+
+.surface__meta {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px;
+}
+
+.surface__scores {
+  display: flex;
+  align-items: baseline;
+  gap: 10px;
+  font-family: var(--mono);
+  font-size: 0.8125rem;
+  color: var(--muted);
+}
+
+.surface__opportunity {
+  font-size: 1.375rem;
+  font-weight: 600;
+  letter-spacing: -0.02em;
+  color: var(--text);
+}
+
+.meter {
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+}
+
+.meter__head {
+  display: flex;
+  justify-content: space-between;
+  font-size: 0.6875rem;
+  letter-spacing: 0.07em;
+  text-transform: uppercase;
+  color: var(--faint);
+}
+
+.meter__track {
+  height: 6px;
+  border-radius: var(--r-pill);
+  background: var(--surface-hover);
+  overflow: hidden;
+}
+
+.meter__fill {
+  height: 100%;
+  border-radius: var(--r-pill);
+  background: var(--accent);
+}
+
+.meter__fill--positive { background: var(--green); }
+.meter__fill--warning { background: var(--amber); }
+
+.jobmap {
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.jobmap__step {
+  display: flex;
+  align-items: baseline;
+  gap: 10px;
+  padding: 9px 12px;
+  border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
+  border-radius: 0 var(--r-sm) var(--r-sm) 0;
+  background: var(--surface);
+  font-size: 0.875rem;
+}
+
+.jobmap__index {
+  font-family: var(--mono);
+  font-size: 0.6875rem;
+  color: var(--accent);
+}
+
+.compare {
+  display: grid;
+  gap: 8px;
+  grid-template-columns: 1fr 1fr;
+}
+
+.compare__col {
+  padding: 12px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-md);
+  font-size: 0.8125rem;
+  line-height: 1.5;
+}
+
+.compare__col--after {
+  border-color: color-mix(in srgb, var(--green) 22%, transparent);
+  background: color-mix(in srgb, var(--green) 6%, transparent);
+}
+
+.compare__col--before {
+  border-color: color-mix(in srgb, var(--red) 20%, transparent);
+  background: color-mix(in srgb, var(--red) 6%, transparent);
+}
+
+.compare__label {
+  display: block;
+  margin-bottom: 6px;
+  font-size: 0.6875rem;
+  font-weight: 600;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  color: var(--faint);
+}
+
+.evidence {
+  padding: 12px 14px;
+  border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
+  border-radius: 0 var(--r-sm) var(--r-sm) 0;
+  background: var(--surface);
+}
+
+.evidence__quote {
+  color: var(--text);
+  font-size: 0.875rem;
+  font-style: italic;
+  line-height: 1.55;
+}
+
+.evidence__meta {
+  display: block;
+  margin-top: 8px;
+  color: var(--faint);
+  font-size: 0.6875rem;
+}
+
+/* ---------------------------------------------------------------- */
+/* Steps                                                            */
+/* ---------------------------------------------------------------- */
+
+.steps {
+  display: grid;
+  gap: 20px;
+  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
+  counter-reset: step;
+}
+
+.step {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  gap: 12px;
+  padding: 26px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-lg);
+  background: var(--surface);
+  counter-increment: step;
+}
+
+.step::before {
+  content: counter(step, decimal-leading-zero);
+  font-family: var(--mono);
+  font-size: 0.6875rem;
+  font-weight: 600;
+  letter-spacing: 0.1em;
+  color: var(--accent);
+}
+
+.step__title {
+  font-size: 1.125rem;
+  font-weight: 600;
+  letter-spacing: -0.01em;
+}
+
+.step__body {
+  color: var(--muted);
+  font-size: 0.9375rem;
+  line-height: 1.6;
+}
+
+/* ---------------------------------------------------------------- */
+/* Connectors                                                       */
+/* ---------------------------------------------------------------- */
+
+.connector-group + .connector-group {
+  margin-top: 36px;
+}
+
+.connector-list {
+  display: grid;
+  gap: 12px;
+  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
+}
+
+.connector {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  padding: 18px 20px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-md);
+  background: var(--surface);
+  transition:
+    transform 0.18s var(--ease-apple-out),
+    border-color 0.18s var(--ease-apple-out);
+}
+
+.connector:hover {
+  transform: translateY(-2px);
+  border-color: var(--line-strong);
+}
+
+.connector__head {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+}
+
+.connector__name {
+  font-size: 0.9375rem;
+  font-weight: 600;
+}
+
+.connector__summary {
+  color: var(--muted);
+  font-size: 0.8125rem;
+  line-height: 1.55;
+}
+
+.connector__env {
+  font-family: var(--mono);
+  font-size: 0.6875rem;
+  color: var(--faint);
+}
+
+/* ---------------------------------------------------------------- */
+/* Code                                                             */
+/* ---------------------------------------------------------------- */
+
+.codeblock {
+  position: relative;
+  margin: 0;
+  padding: 20px 22px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-md);
+  background: var(--bg-sunken);
+  overflow-x: auto;
+  font-family: var(--mono);
+  font-size: 0.875rem;
+  line-height: 1.65;
+  color: var(--text);
+  tab-size: 2;
+}
+
+.codeblock code {
+  font-family: var(--mono);
+}
+
+.copy-btn {
+  position: absolute;
+  top: 10px;
+  right: 10px;
+  padding: 5px 12px;
+  border: 1px solid var(--line-strong);
+  border-radius: var(--r-pill);
+  background: var(--bg-raised);
+  color: var(--muted);
+  font-family: var(--font);
+  font-size: 0.75rem;
+  font-weight: 600;
+  opacity: 0;
+  transition:
+    opacity 0.15s var(--ease-tactile),
+    color 0.15s var(--ease-tactile),
+    border-color 0.15s var(--ease-tactile);
+}
+
+.codeblock:hover .copy-btn,
+.copy-btn:focus-visible {
+  opacity: 1;
+}
+
+.copy-btn:hover {
+  color: var(--text);
+  border-color: var(--line-strong);
+}
+
+/* Syntax highlighting, server-rendered by Pygments. */
+.highlight {
+  margin: 0;
+  padding: 20px 22px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-md);
+  background: var(--bg-sunken);
+  overflow-x: auto;
+  font-family: var(--mono);
+  font-size: 0.875rem;
+  line-height: 1.65;
+}
+
+.highlight pre {
+  margin: 0;
+  font-family: var(--mono);
+}
+
+.highlight code {
+  font-family: var(--mono);
+}
+
+/* ---------------------------------------------------------------- */
+/* Tabs                                                             */
+/* ---------------------------------------------------------------- */
+
+.tabs__list {
+  display: inline-flex;
+  gap: 4px;
+  padding: 4px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-pill);
+  background: var(--surface);
+}
+
+.tabs__tab {
+  padding: 8px 18px;
+  border-radius: var(--r-pill);
+  font-size: 0.875rem;
+  font-weight: 500;
+  color: var(--muted);
+  transition:
+    background-color 0.15s var(--ease-tactile),
+    color 0.15s var(--ease-tactile);
+}
+
+.tabs__tab[aria-selected="true"] {
+  background: var(--surface-hover);
+  color: var(--text);
+}
+
+.tabs__panel {
+  margin-top: 20px;
+}
+
+.tabs__panel[hidden] {
+  display: none;
+}
+
+/* ---------------------------------------------------------------- */
+/* Endpoints                                                        */
+/* ---------------------------------------------------------------- */
+
+.endpoints {
+  display: flex;
+  flex-direction: column;
+  gap: 0;
+  border: 1px solid var(--line);
+  border-radius: var(--r-md);
+  overflow: hidden;
+}
+
+.endpoint {
+  display: grid;
+  gap: 4px 20px;
+  grid-template-columns: minmax(0, 1fr);
+  padding: 18px 22px;
+  background: var(--surface);
+}
+
+.endpoint + .endpoint {
+  border-top: 1px solid var(--line);
+}
+
+@media (min-width: 760px) {
+  .endpoint {
+    grid-template-columns: 200px minmax(0, 1fr);
+    align-items: center;
+  }
+}
+
+.endpoint__name {
+  font-size: 0.875rem;
+  font-weight: 600;
+}
+
+.endpoint__url {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  font-family: var(--mono);
+  font-size: 0.8125rem;
+  color: var(--muted);
+  overflow-wrap: anywhere;
+}
+
+.endpoint__note {
+  grid-column: 1 / -1;
+  color: var(--faint);
+  font-size: 0.8125rem;
+  line-height: 1.5;
+}
+
+/* ---------------------------------------------------------------- */
+/* Tools preview                                                    */
+/* ---------------------------------------------------------------- */
+
+.tool {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  padding: 18px 20px;
+  border: 1px solid var(--line);
+  border-radius: var(--r-md);
+  background: var(--surface);
+}
+
+.tool__name {
+  font-family: var(--mono);
+  font-size: 0.875rem;
+  font-weight: 600;
+  color: var(--accent);
+}
+
+.tool__purpose {
+  color: var(--muted);
+  font-size: 0.875rem;
+  line-height: 1.55;
+}
+
+.tool__sig {
+  font-family: var(--mono);
+  font-size: 0.75rem;
+  color: var(--faint);
+  overflow-wrap: anywhere;
+}
+
+/* ---------------------------------------------------------------- */
+/* Status                                                           */
+/* ---------------------------------------------------------------- */
+
+.status-grid {
+  display: grid;
+  gap: 20px;
+  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
+}
+
+.status-list {
+  display: flex;
+  flex-direction: column;
+  gap: 12px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.status-list li {
+  display: flex;
+  align-items: baseline;
+  gap: 10px;
+  color: var(--muted);
+  font-size: 0.9375rem;
+  line-height: 1.55;
+}
+
+.status-list li::before {
+  content: "";
+  flex: none;
+  width: 5px;
+  height: 5px;
+  margin-top: 9px;
+  border-radius: 50%;
+  background: var(--accent);
+}
+
+.status-note {
+  margin-top: 40px;
+  font-size: 1.125rem;
+  font-weight: 600;
+  letter-spacing: -0.01em;
+}
+
+/* ---------------------------------------------------------------- */
+/* Motion                                                           */
+/* ---------------------------------------------------------------- */
+
+@keyframes hero-in {
+  from {
+    opacity: 0;
+    transform: translateY(10px);
+    filter: blur(4px);
+  }
+  to {
+    opacity: 1;
+    transform: none;
+    filter: blur(0);
+  }
+}
+
+@keyframes reveal-up {
+  from {
+    opacity: 0;
+    transform: translateY(24px);
+  }
+  to {
+    opacity: 1;
+    transform: none;
+  }
+}
+
+@keyframes surface-in {
+  from {
+    opacity: 0;
+    transform: translateY(10px) scale(0.985);
+  }
+  to {
+    opacity: 1;
+    transform: none;
+  }
+}
+
+@keyframes caret-blink {
+  0%, 45% { opacity: 1; }
+  46%, 100% { opacity: 0; }
+}
+
+.hero__eyebrow { animation: hero-in 0.7s var(--ease-apple-out) both; }
+.hero__title    { animation: hero-in 0.7s var(--ease-apple-out) 0.09s both; }
+.hero__sub      { animation: hero-in 0.7s var(--ease-apple-out) 0.18s both; }
+.hero__actions  { animation: hero-in 0.7s var(--ease-apple-out) 0.27s both; }
+.hero__cue      { animation: hero-in 0.7s var(--ease-apple-out) 0.36s both; }
+
+/* Reveal-on-scroll. Content is visible by default; the observer opts it
+   into the hidden state only after it loads, so no-JS readers never lose
+   anything. */
+.js-reveal [data-reveal] {
+  opacity: 0;
+  transform: translateY(24px);
+  transition:
+    opacity 0.8s var(--ease-apple-out),
+    transform 0.8s var(--ease-apple-out);
+}
+
+.js-reveal [data-reveal].is-visible {
+  opacity: 1;
+  transform: none;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  html {
+    scroll-behavior: auto;
+  }
+
+  *,
+  *::before,
+  *::after {
+    animation-duration: 0.001ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: 0.001ms !important;
+    scroll-behavior: auto !important;
+  }
+
+  .js-reveal [data-reveal] {
+    opacity: 1;
+    transform: none;
+  }
+}
+
+/* ---------------------------------------------------------------- */
+/* Responsive                                                       */
+/* ---------------------------------------------------------------- */
+
+@media (max-width: 860px) {
+  .site-nav {
+    display: none;
+  }
+}
+
+@media (max-width: 640px) {
+  .compare {
+    grid-template-columns: 1fr;
+  }
+
+  .gap__row {
+    grid-template-columns: 78px 1fr 34px;
+    gap: 10px;
+  }
+}

